export interface DistrictGeoData {
  isoCode: string;
  slug: string;
  name: string;
  shortName: string;
  chefLieu: string;
  center: [number, number];
  regions: string[];
  path: string;
}

export type CityType = 'metropole' | 'capitale' | 'port' | 'ville';

export interface CityGeoData {
  id: string;
  name: string;
  type: CityType;
  population: string;
  districtSlug: string;
  x: number;
  y: number;
  description: string;
}

export interface AbidjanCommuneGeoData {
  id: string;
  name: string;
  zone: string;
  density: string;
  center: [number, number];
  path: string;
}

